+import assert from "node:assert/strict";
+import test from "node:test";
+import { validateEmail } from "../src/index.js";
+
+test("validateEmail accepts practical ordinary addresses", () => {
+  const accepted = [
+    "user@example.com",
+    "first.last+tag@example.co.uk",
+    "person@mail.example.com",
+  ];
+
+  for (const value of accepted) {
+    assert.equal(validateEmail(value), true, value);
+  }
+});
+
+test("validateEmail rejects malformed addresses", () => {
+  const rejected = [
+    "userexample.com",
+    "@example.com",
+    "user@",
+    "user@example",
+    "user @example.com",
+    " user@example.com",
+    "user@example.com ",
+    "",
+    "   ",
+    ".user@example.com",
+    "user.@example.com",
+    "first..last@example.com",
+    "user@example..com",
+  ];
+
+  for (const value of rejected) {
+    assert.equal(validateEmail(value), false, value);
+  }
+});
+
+test("validateEmail returns false without throwing for non-string inputs", () => {
+  const rejected = [null, undefined, 42, {}, [], true, Symbol("email")];
+
+  for (const value of rejected) {
+    assert.doesNotThrow(() => validateEmail(value));
+    assert.equal(validateEmail(value), false);
+  }
+});
